import sympy
from sympy import ZZ, QQ
import math

# Top-level setup for potential witness expressions
Z = sympy.S.Integers
Q = sympy.S.Rationals

CONDITION_LABELS = [
    "H_1: R is a commutative ring with identity",
    "H_2: I is a finitely generated ideal of R",
    "¬Q: I is not generated by any idempotent element in R"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness) -> list[bool]:
    """
    Evaluates the hypotheses and the negated conclusion for the given witness.
    The witness is expected to be a tuple (R, I), where:
      - R is an integer n >= 0 (representing the ring Z/nZ, or Z if n=0), 
        or a SymPy ring like ZZ or QQ.
      - I is a list of generators for the ideal.
    """
    try:
        if not isinstance(witness, (tuple, list)) or len(witness) != 2:
            return [False, False, False]
            
        R, I = witness
        
        h1 = False
        h2 = False
        neg_q = False
        
        # H2: I is a finitely generated ideal
        if isinstance(I, (list, tuple, set)):
            h2 = True
        else:
            return [False, False, False]
            
        # Case 1: R is an integer n >= 0 (representing Z/nZ or Z)
        if type(R) is int or (hasattr(R, 'is_Integer') and R.is_Integer):
            n = int(R)
            if n >= 0:
                h1 = True
                gens = [int(g) for g in I]
                if n == 0:
                    # Ring is Z
                    g = 0
                    for gen in gens:
                        g = math.gcd(g, abs(gen))
                    # Idempotents in Z are 0 and 1
                    neg_q = (g != 0 and g != 1)
                else:
                    # Ring is Z/nZ
                    g = n
                    for gen in gens:
                        g = math.gcd(g, gen % n)
                    # Find all idempotents in Z/nZ
                    idempotents = [e for e in range(n) if (e * e) % n == e]
                    # The ideal generated by an idempotent e is <gcd(e, n)>
                    has_idemp = any(math.gcd(e, n) == g for e in idempotents)
                    neg_q = not has_idemp
                return [h1, h2, neg_q]
                
        # Case 2: R is Z (SymPy Integers)
        if R == sympy.S.Integers or R == ZZ:
            h1 = True
            gens = [int(g) for g in I]
            g = 0
            for gen in gens:
                g = math.gcd(g, abs(gen))
            neg_q = (g != 0 and g != 1)
            return [h1, h2, neg_q]
            
        # Case 3: R is Q (SymPy Rationals)
        if R == sympy.S.Rationals or R == QQ:
            h1 = True
            # In a field, all ideals (<0> and <1>) are generated by idempotents (0 and 1)
            neg_q = False
            return [h1, h2, neg_q]
            
    except Exception:
        pass
        
    return [False, False, False]